def transform(grid):
    h, w = len(grid), len(grid[0])

    # Grid dividers are the color forming complete rows and columns.
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    divider = None
    for r in row_lines:
        color = grid[r][0]
        if any(grid[rr][c] == color for rr in range(h) for c in col_lines):
            divider = color
            break
    if divider is None:
        divider = grid[row_lines[0]][0]

    row_lines = [r for r in range(h) if all(v == divider for v in grid[r])]
    col_lines = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    rb = [-1] + row_lines + [h]
    cb = [-1] + col_lines + [w]
    result = []
    for i in range(len(rb) - 1):
        row = []
        for j in range(len(cb) - 1):
            n = sum(
                grid[r][c] == 5
                for r in range(rb[i] + 1, rb[i + 1])
                for c in range(cb[j] + 1, cb[j + 1])
            )
            row.append(1 if n >= 2 else 3)
        result.append(row)
    return result
